import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{_t as i,bt as a,vt as o,yt as s}from"./chunks/assets.DAjhvrpn.js";var c=JSON.parse(`{"title":"Stage","description":"","frontmatter":{"title":"Stage","lang":"en-US"},"headers":[],"relativePath":"maintenance/stage.md","filePath":"maintenance/stage.md"}`),l={name:`maintenance/stage.md`};function u(n,c,l,u,d,f){return e(),r(`div`,null,[...c[0]||=[t(`<h1 id="stage" tabindex="-1">Stage <a class="header-anchor" href="#stage" aria-label="Permalink to “Stage”">​</a></h1><p>Maintenance of the stage consists mainly of replacing the ball and calibrating the optical flow sensor.</p><h2 id="running-ball-replacement" tabindex="-1">Running ball replacement <a class="header-anchor" href="#running-ball-replacement" aria-label="Permalink to “Running ball replacement”">​</a></h2><ol><li><p>Glue two <a href="https://www.dickblick.com/items/smooth-foam-crafters-foam-half-ball-8-dia/" target="_blank" rel="noreferrer">8&quot; diameter half balls</a> together with <a href="https://www.amazon.com/FloraCraft-Non-Toxic-Foam-Glue/dp/B000FFUCAI?th=1" target="_blank" rel="noreferrer">lightweight Styrofoam glue</a>. Use a fair amount of glue, press the halves together (squeeze them for a few seconds so they stay stuck to each other) and smooth the excess glue along the seam with your finger. Let the ball sit for a few hours or overnight.</p></li><li><p>Once it has set, use an <a href="https://www.mcmaster.com/7451T32/" target="_blank" rel="noreferrer">abrasive brush</a> or a <a href="https://www.mcmaster.com/4023A79/" target="_blank" rel="noreferrer">sanding sponge</a> to slightly roughen the surface of the ball; this improves the quality of motion detection by the optical flow sensor.</p></li><li><p>Once the Styrofoam ball is prepared, label it with a red Sharpie, then mark it with a cross-hatch pattern using a black industrial Sharpie, trying not to leave large white gaps in the pattern.</p></li></ol><h2 id="optical-flow-sensor-calibration" tabindex="-1">Optical flow sensor calibration <a class="header-anchor" href="#optical-flow-sensor-calibration" aria-label="Permalink to “Optical flow sensor calibration”">​</a></h2><h3 id="image-quality-and-lens-focus" tabindex="-1">Image quality and lens focus <a class="header-anchor" href="#image-quality-and-lens-focus" aria-label="Permalink to “Image quality and lens focus”">​</a></h3><p>The image quality of the optical sensor should be maximized for reliable measurements. You can do this by:</p><ul><li><p>Ensuring sufficient infrared (IR) illumination (but increasing it past a certain threshold does not help).</p></li><li><p>Adjusting the focal plane of the M12 lens to the surface being measured.</p></li><li><p>Using a surface with more texture (of the appropriate size given the limited number of sensor pixels).</p></li></ul><p>The ADNS-3080 chip reports a surface quality (SQUAL) value that can be read out in software, as explained below. This value needs to be at least 30 for velocities of around 100-150 cm/s. At lower SQUAL values, the sensor tends to underestimate the actual displacement, and the effect grows with surface velocity. Below are example images of a Styrofoam ball at SQUAL values ranging from unusable to ideal (for velocities not far above 100 cm/s).</p><figure><img src="`+a+`" alt="" width="1280" height="437" loading="lazy"></figure><p>Follow the procedure below to adjust the focus of the optical flow sensor lens.</p><ol><li><p>Load <code>Arduino Code\\ADNS_image_v1\\ADNS_image_v1.ino</code> in the Arduino IDE.</p></li><li><p>Set <code>reset_pin</code> to 6 and <code>select_pin</code> to 10 (lines 20-24).</p></li><li><p>Upload the Arduino code to the board. Note that you will have to reprogram the board afterwards to use it for displacement readout.</p></li><li><p>Print the left side of the following image (an optical spoke target) on a laser printer. The spoke target&#39;s lines narrow toward the center, which lets you probe the single-pixel limit of the optical sensor, as shown in the calibrated image (from the sensor) on the right:</p></li></ol><figure><img src="`+s+`" alt="" width="1280" height="437" loading="lazy"></figure><ol start="5"><li><p>Place the spoke target in front of the optical sensor at the same location and orientation as the actual surface to be measured. For example, on the mouse VR rig, tape it onto a Styrofoam ball and suspend the ball at the height it would normally be during experiments.</p></li><li><p>Run the <code>Matlab Code\\Calibration\\display_image.m</code> function. It continuously displays the sensor image for a preset amount of time and can be stopped with Ctrl+C.</p></li><li><p>Adjust the IR LED so that it points toward the center of the surface being imaged. You should see the illuminated region shift around in the <code>display_image</code> figure.</p></li><li><p>The <code>display_image</code> figure is normalized so that the brightest regions appear white and the darkest black, i.e. absolute luminosity information is not shown. You can change this by replacing <code>imagesc(im)</code> (line 66) with <code>image(im)</code> in the code and setting the color scale manually: <code>set(gca, &#39;CLim&#39;, […])</code>. Oblique illumination can help increase feature contrast on uneven surfaces, but in general just illuminating the largest amount of surface available is sufficient.</p></li><li><p>Adjust the focus of the optical sensor lens by rotating it. If you’re turning it the right way, you should see the spoke target lines get sharper and the SQUAL value increase. You should be able to find a distance at which the SQUAL value peaks (there is a fair amount of leeway).</p></li><li><p>Replace the spoke target with the actual surface to be measured, and verify that the SQUAL value is still high enough (well above 30). Values of 50-80 have been achieved with Styrofoam balls, at the higher end once they have been “weathered” by running mice.</p></li><li><p>If the SQUAL value is around 30 or lower, consider using a more textured surface; for example, scour the Styrofoam ball with steel wool.</p></li></ol><h3 id="lenght-scale-calibration" tabindex="-1">Length scale calibration <a class="header-anchor" href="#lenght-scale-calibration" aria-label="Permalink to “Length scale calibration”">​</a></h3><p>Follow the procedure below to calibrate the length scale of the optical flow sensor.</p><ol><li><p>Load <code>Arduino Code\\ADNS_aout_wUSB_1sensor\\ADNS_aout_wUSB_1sensor.ino</code> in the Arduino IDE.</p></li><li><p>Upload the Arduino code to the board.</p></li><li><p>Mount a Styrofoam ball on an axle (or use a cylindrical Styrofoam wheel) at the position it would have relative to the optical sensor in a real experiment. Mark a reference position on the ball, e.g. with a piece of black tape, as shown in the mouse VR calibration photo below.</p></li></ol><figure><img src="`+o+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="4"><li><p>Before continuing, make sure that <code>Matlab Code\\Calibration\\calibrateBall.m</code> is either in MATLAB&#39;s current folder or on the MATLAB path.</p></li><li><p>While holding the ball in place, run the <code>calibrateBall</code> script.</p></li><li><p>Spin the ball 10 times (this can be done quickly), counting how many times the black tape returns to roughly its original position.</p></li><li><p>If necessary, rotate the ball a little further until the tape is exactly at its original position. This cancels out errors from the previous step.</p></li><li><p>Stop <code>calibrateBall</code> by pressing Ctrl+C.</p></li><li><p>Enter <code>fclose(instrfindall)</code> at the MATLAB command line to close communication with the Arduino.</p></li><li><p>Enter <code>[dx,dy]</code> at the MATLAB command line to view the accumulated displacements. If the optical sensor is correctly aligned with the ball&#39;s axis of rotation, one of these displacements should be large (thousands or more) and the other small (tens or less).</p></li><li><p>Below, the measured displacement along the axis of interest is called <em>nDots</em>, and the number of revolutions <em>nRev</em>.</p></li><li><p>Repeat the measurement until you are satisfied (with more rotations if necessary), then enter the resulting constants in <code>RigParameters.m</code>.</p></li></ol><ul><li><strong>ballCircumference</strong>: Actual displacement (e.g. in cm) of the calibration surface per revolution. For an 8&quot; diameter Styrofoam ball, this is its circumference, 63.8 cm.</li><li><strong>sensorDotsPerRev</strong>: This should be set directly to <em>nDots/nRev</em> in the case of a single sensor. For two sensors, use <code>sensorDotsPerRev = RigParameters.sensorCalibration()</code> and set <code>sensorCalibration</code> as described below.</li><li><strong>sensorCalibration</strong>: Only used with two sensors, which may have different constants. Use the appropriate <code>MovementSensor</code> label for each sensor to record <code>dotsPerRev</code>, e.g.: <code>dotsPerRev(MovementSensor.FrontVelocity) = nDots/nRev;</code></li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><p>Troubleshoot in this order: first clean the 3D printed cup and its window and make sure the ball is in good condition, then replace the optical flow sensor if necessary, and finally check the Arduino. For Arduino problems, see below.</p><h3 id="arduino-not-recognized" tabindex="-1">Arduino not recognized <a class="header-anchor" href="#arduino-not-recognized" aria-label="Permalink to “Arduino not recognized”">​</a></h3><p>If the Arduino is not recognized by the rig tester&#39;s Arduino detection button, follow these steps:</p><ol><li><p>First check whether the computer detects the Arduino: open Device Manager (type &quot;device manager&quot; in the search bar) and expand Ports (COM &amp; LPT) to see the connected devices.</p><ul><li>If the Arduino is listed there, the COM port might have changed. Make sure the COM port listed in Device Manager matches the <code>arduinoPort</code> variable in the rig parameters file. Restart MATLAB and try again.</li></ul></li><li><p>If the Arduino is not listed in Device Manager, either the cable or the Arduino is faulty. Start with the Arduino (cables can be harder to check, since they often take intricate paths behind the rig).</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Before removing the Arduino from its box, you can quickly rule out the cable: unplug the USB cable from the black box on the DIN rail and connect it to a new Arduino. If the new one is recognized in Device Manager, continue with the steps below; otherwise, replace the cable.</p></div><ul><li><p>Disconnect both the cable and the connector from the black box holding the Arduino and take the box off the DIN rail (push it down slightly and pull the bottom toward you).</p></li><li><p>Open the box by removing the 4 screws holding the cover, then the 2 screws holding the Arduino in the 3D printed box.</p></li><li><p>Replace the Arduino with a new one, screw it into the box and screw the cover back on. Put the box back on the DIN rail and connect the sensor cable first, then the USB cable.</p></li><li><p>Program the Arduino following <a href="/building/control.html#programming-the-arduino">these instructions</a>.</p></li></ul></li><li><p>If the cable is faulty, replace it. We recommend a <a href="https://www.bhphotovideo.com/c/product/1387544-REG/tether_tools_cuc2515_blk_tetherpro_usb_c_to_2_0.html?sts=pi&amp;pim=Y" target="_blank" rel="noreferrer">USB Type-C male to micro-USB Type-B male cable</a>, or any other cable that matches your setup, as long as it is a single tether cable or USB 3.0 cable. Avoid chaining multiple cables or hubs (or make sure everything is rated for high speed).</p></li></ol><h3 id="timed-out-while-waiting-for-a-reply" tabindex="-1">Timed out while waiting for a reply <a class="header-anchor" href="#timed-out-while-waiting-for-a-reply" aria-label="Permalink to “Timed out while waiting for a reply”">​</a></h3><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><p>This error can be caused by corrupted firmware on the Arduino. To fix it, program the Arduino again following <a href="/building/control.html#programming-the-arduino">these instructions</a>.</p>`,28)]])}var d=n(l,[[`render`,u]]);export{c as __pageData,d as default};